package com.lyrashop.order.controller;
import java.util.*;import org.springframework.http.*;import org.springframework.security.access.prepost.PreAuthorize;import org.springframework.web.bind.annotation.*;import com.lyrashop.order.dto.*;import com.lyrashop.order.service.VoucherService;import jakarta.validation.Valid;
@RestController @RequestMapping("/api/v1/admin/vouchers") @PreAuthorize("hasRole('ADMIN')")
public class AdminVoucherController{private final VoucherService service;public AdminVoucherController(VoucherService service){this.service=service;}@GetMapping public List<AdminVoucherResponse> list(){return service.adminList();}@PostMapping public ResponseEntity<AdminVoucherResponse> create(@Valid @RequestBody AdminVoucherRequest r){return ResponseEntity.status(201).body(service.adminCreate(r));}@PutMapping("/{id}") public AdminVoucherResponse update(@PathVariable UUID id,@Valid @RequestBody AdminVoucherRequest r){return service.adminUpdate(id,r);}@DeleteMapping("/{id}") public ResponseEntity<Void> delete(@PathVariable UUID id){service.adminDeactivate(id);return ResponseEntity.noContent().build();}}
